// Adapted from the portal's supplied concept 04, "A Clearer Picture".
// The original renderer and logo are retained; lifecycle is bounded and skippable.
(()=>{
if(matchMedia('(prefers-reduced-motion: reduce)').matches||location.pathname.startsWith('/demo'))return;
const layer=document.createElement('div');layer.className='m0ve-preloader';layer.innerHTML='<canvas aria-hidden="true"></canvas><button type="button">Skip intro</button>';document.body.append(layer);
const canvas=layer.querySelector('canvas'),ctx=canvas.getContext('2d');if(!ctx){layer.remove();return;}
let w=innerWidth,h=innerHeight,raf=0,done=false;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);
const clamp=x=>Math.max(0,Math.min(1,x)),mix=(a,b,t)=>a+(b-a)*t,ease=x=>1-Math.pow(1-clamp(x),3);
const logo=new Image();logo.src='data:image/png;base64,';
function text(s,x,y,size,color='#f8f6f2',align='center',weight=400){ctx.fillStyle=color;ctx.font=weight+' '+size+'px Arial';ctx.textAlign=align;ctx.fillText(s,x,y)}
function brand(x,y,width,alpha=1){ctx.save();ctx.globalAlpha=alpha;if(logo.complete&&logo.naturalWidth)ctx.drawImage(logo,x-width/2,y-width*.136,width,width*.272);else text('M0VE',x,y+12,width*.27,'#192f3e');ctx.restore()}
function line(points,p,color='#7651ff',width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();const lengths=points.slice(1).map((v,i)=>Math.hypot(v[0]-points[i][0],v[1]-points[i][1]));let total=lengths.reduce((a,b)=>a+b,0)*clamp(p);ctx.moveTo(...points[0]);for(let i=0;i<lengths.length;i++){let f=Math.min(1,total/lengths[i]);ctx.lineTo(mix(points[i][0],points[i+1][0],f),mix(points[i][1],points[i+1][1],f));total-=lengths[i];if(total<=0)break}ctx.stroke()}
function base(color){ctx.fillStyle=color;ctx.fillRect(0,0,w,h)}function micro(label,t,color){text(label,w*.07,h*.90,Math.max(9,w*.011),color,'left');text(String(Math.min(100,Math.floor(t*100))).padStart(3,'0'),w*.93,h*.9,Math.max(11,w*.014),color,'right')}



function blueprint(t){let exit=ease((t-.78)/.22);ctx.save();ctx.translate(0,-h*exit);base('#f8f6f2');let x=w/2,y=h*.49,s=Math.min(w*.28,h*.39);ctx.save();ctx.globalAlpha=(1-ease((t-.51)/.15))*.5;for(let i=-4;i<=4;i++){line([[x+i*s/3,0],[x+i*s/3,h]],1,'#192f3e0d');line([[0,y+i*s/3],[w,y+i*s/3]],1,'#192f3e0d')}ctx.restore();ctx.save();ctx.globalAlpha=1-ease((t-.52)/.15);let paths=[[[-1,.7],[-1,-.25],[0,-1],[1,-.25],[1,.7],[-1,.7]],[[-1.2,-.18],[0,-1.15],[1.2,-.18]],[[-.18,.7],[-.18,.05],[.22,.05],[.22,.7]],[[-.73,-.1],[-.38,-.1],[-.38,.24],[-.73,.24],[-.73,-.1]],[[.44,-.1],[.79,-.1],[.79,.24],[.44,.24],[.44,-.1]],[[-1.25,.88],[1.25,.88]]];paths.forEach((pts,i)=>line(pts.map(p=>[x+p[0]*s*.7,y+p[1]*s*.7]),ease((t-i*.045)/.28),i===1?'#7651ff':'#192f3e',i===1?2:1.1));ctx.restore();brand(x,y,w*.30,ease((t-.54)/.12));text(t<.55?'Every detail. A clearer picture.':'Property. Made clearer.',x,h*.77,Math.max(14,w*.023),'#192f3e');micro('BRINGING IT ALL TOGETHER',t/.78,'#63727b');ctx.restore()}
const finish=()=>{if(done)return;done=true;cancelAnimationFrame(raf);clearTimeout(safety);document.removeEventListener('keydown',key);layer.remove();};
const key=e=>{if(e.key==='Escape')finish()};document.addEventListener('keydown',key);
layer.querySelector('button').onclick=()=>{finish();(document.querySelector('main')||document.body).focus({preventScroll:true});};
const safety=setTimeout(finish,2200),start=performance.now();
function frame(now){if(done)return;const t=clamp((now-start)/1500);ctx.clearRect(0,0,w,h);blueprint(t);if(t<1)raf=requestAnimationFrame(frame);else finish();}
raf=requestAnimationFrame(frame);addEventListener('pagehide',finish,{once:true});
})();
